/**
 * Phase 1: 100% Exact eye.py ASCII Engine in Live JavaScript Canvas
 * Renders the exact 990 frames generated by eye.py:
 * - Real eyelid curve physics
 * - Iris fiber textures & pupil zoom
 * - Eyelashes, twinkling stars & meteor streaks
 * - Heart nebula with exact procedural noise
 * - Seamless in-place ASCII dissolve to "I LOVE YOU "
 */
class EyeScene {
  constructor(canvas) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');

    // Exact 95-char RAMP from eye.py (RAMP_BASE + [c for c in EXTRA_CHARS if c not in RAMP_BASE])
    this.RAMP = " .'`^\",:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$ADEFGHKNPRSTVegsy23456793";
    this.isLoaded = false;

    // Precompute RGB color lookup table (QL = 24)
    this.colorTable = [];
    for (let r = 0; r < 24; r++) {
      this.colorTable[r] = [];
      for (let g = 0; g < 24; g++) {
        this.colorTable[r][g] = [];
        for (let b = 0; b < 24; b++) {
          const red = Math.floor(r * 255 / 23);
          const green = Math.floor(g * 255 / 23);
          const blue = Math.floor(b * 255 / 23);
          this.colorTable[r][g][b] = `rgb(${red},${green},${blue})`;
        }
      }
    }

    this.loadData();
  }

  async loadData() {
    try {
      const resp = await fetch('eye_data.bin');
      const buf = await resp.arrayBuffer();
      // Decompress with pako
      const decomp = pako.inflate(new Uint8Array(buf));
      const dv = new DataView(decomp.buffer, decomp.byteOffset, decomp.byteLength);

      this.cols = dv.getUint32(0, true);
      this.rows = dv.getUint32(4, true);
      this.cw_orig = dv.getUint32(8, true);
      this.ch_orig = dv.getUint32(12, true);
      this.totalFrames = dv.getUint32(16, true);

      this.cellsPerFrame = this.cols * this.rows;
      this.frameBytes = this.cellsPerFrame * 4; // 1 byte idx + 3 bytes q

      this.dataBytes = new Uint8Array(decomp.buffer, decomp.byteOffset + 20);
      this.isLoaded = true;
      console.log(`[EyeScene] Loaded exact eye.py data: ${this.cols}x${this.rows}, ${this.totalFrames} frames`);
    } catch (err) {
      console.error("[EyeScene] Error loading eye_data.bin:", err);
    }
  }

  resize(w, h) {
    this.w = w;
    this.h = h;
    // Scale cell size to fit 1280x720 aspect ratio comfortably on screen
    if (this.cols && this.rows) {
      this.calcDimensions();
    }
  }

  calcDimensions() {
    const isPortrait = this.h > this.w;
    if (!isPortrait) {
      // Landscape / Desktop / Widescreen:
      // Fill the entire screen edge-to-edge with 0px margins on left and right!
      this.cw = this.w / this.cols;
      this.ch = this.h / this.rows;
      this.gridW = this.w;
      this.gridH = this.h;
      this.startX = 0;
      this.startY = 0;
      this.fontSize = Math.floor(this.ch * 0.92);
    } else {
      // Portrait / Mobile:
      // Fill full width edge-to-edge (startX = 0, gridW = w)
      // and center vertically with balanced cell proportions
      this.cw = this.w / this.cols;
      this.ch = this.cw * 1.85;
      this.gridW = this.w;
      this.gridH = this.rows * this.ch;
      this.startX = 0;
      this.startY = Math.floor((this.h - this.gridH) / 2);
      this.fontSize = Math.max(6, Math.floor(this.ch * 0.90));
    }
  }

  render(t) {
    const ctx = this.ctx;
    ctx.fillStyle = "#010203";
    ctx.fillRect(0, 0, this.w, this.h);

    if (!this.isLoaded) return;
    if (!this.gridW) this.calcDimensions();

    const frameIdx = Math.min(this.totalFrames - 1, Math.max(0, Math.floor(t * 30.0)));
    const frameOffset = frameIdx * this.frameBytes;

    const idxBytes = this.dataBytes.subarray(frameOffset, frameOffset + this.cellsPerFrame);
    const qBytes = this.dataBytes.subarray(frameOffset + this.cellsPerFrame, frameOffset + this.frameBytes);

    ctx.font = `bold ${this.fontSize || Math.floor(this.ch * 0.92)}px Consolas, Monaco, "Courier New", monospace`;
    ctx.textBaseline = "middle";
    ctx.textAlign = "center";

    const RAMP = this.RAMP;
    const colorTable = this.colorTable;
    const startX = this.startX;
    const startY = this.startY;
    const cw = this.cw;
    const ch = this.ch;
    const cols = this.cols;
    const rows = this.rows;

    for (let r = 0; r < rows; r++) {
      const py = startY + (r + 0.5) * ch;
      const rowOffset = r * cols;

      for (let c = 0; c < cols; c++) {
        const cell = rowOffset + c;
        const charCode = idxBytes[cell];
        if (charCode === 0) continue;

        const charSym = RAMP[charCode];
        if (charSym === ' ') continue;

        const qIdx = cell * 3;
        const qr = qBytes[qIdx];
        const qg = qBytes[qIdx + 1];
        const qb = qBytes[qIdx + 2];

        if (qr === 0 && qg === 0 && qb === 0) continue;

        ctx.fillStyle = colorTable[qr][qg][qb];
        ctx.fillText(charSym, startX + (c + 0.5) * cw, py);
      }
    }
  }
}
window.EyeScene = EyeScene;
